select sub.slug, lvl.level::text as level, t.slug as topic, count(distinct m.id) filter (where m.material_type='notes') as notes_n, min(length(m.content)) filter (where m.material_type='notes') as notes_min, count(distinct m.id) filter (where lower(replace(m.material_type,'_','-'))='exam-technique') as tech_n, min(length(m.content)) filter (where lower(replace(m.material_type,'_','-'))='exam-technique') as tech_min, count(distinct q.id) as qs, count(distinct q.id) filter (where q.difficulty='exam') as exam_qs from public.topics t join public.subject_levels lvl on lvl.id=t.subject_level_id join public.subjects sub on sub.id=lvl.subject_id left join public.study_materials m on m.topic_id=t.id left join public.quizzes z on z.topic_id=t.id left join public.questions q on q.quiz_id=z.id group by sub.slug, lvl.level, t.slug order by qs asc, notes_min nulls first limit 60;
